// Written by scripts/build-sat-bank.mjs. Do not edit by hand.
// The free SAT questions. The rest are sent by the server to Pro accounts.
export const FREE_BANK = [{"id":"rw-wic-1","section":"rw","domain":"cs","skill":"wic","level":1,"type":"mc","passage":"Although the river looks calm from the bank, its currents are ______: swimmers who enter it without a guide are often pulled far downstream within seconds.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["predictable","scenic","treacherous","shallow"],"answer":2,"explain":"The second half describes hidden danger, so \"treacherous\" (dangerous in a way that is not obvious) fits."},{"id":"rw-wic-2","section":"rw","domain":"cs","skill":"wic","level":1,"type":"mc","passage":"The museum's new exhibit is intentionally ______: instead of displaying hundreds of objects, the curators chose just twelve, giving each one its own room.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["hurried","accidental","selective","crowded"],"answer":2,"explain":"Choosing only twelve objects on purpose is being selective."},{"id":"rw-wic-8","section":"rw","domain":"cs","skill":"wic","level":2,"type":"mc","passage":"The biologist cautioned that her results were ______: the study involved only fifteen frogs from a single pond, so broader conclusions would have to wait for further research.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["irrelevant","preliminary","fraudulent","definitive"],"answer":1,"explain":"A small first study whose conclusions must wait is preliminary."},{"id":"rw-wic-9","section":"rw","domain":"cs","skill":"wic","level":2,"type":"mc","passage":"Far from being ______ by the failure of her first company, the entrepreneur treated the experience as training, founding a second firm within a year.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["funded","deterred","recognized","encouraged"],"answer":1,"explain":"\"Far from\" signals the opposite of what happened. She kept going, so she was not deterred (discouraged)."},{"id":"rw-wic-15","section":"rw","domain":"cs","skill":"wic","level":3,"type":"mc","passage":"The senator's statement was carefully ______: by praising the goals of the bill without saying how she would vote, she kept both supporters and opponents hopeful.","question":"Which choice completes the text with the most logical and precise word or phrase?","options":["candid","noncommittal","redundant","hostile"],"answer":1,"explain":"She avoided taking a side, which is being noncommittal. \"Candid\" (frank) is the opposite."},{"id":"rw-tsp-1","section":"rw","domain":"cs","skill":"tsp","level":1,"type":"mc","passage":"Many people think of deserts as lifeless, but the Sonoran Desert supports more than 2,000 plant species. Its two rainy seasons, one in winter and one in summer, allow far more growth than a single season would.","question":"Which choice best states the main purpose of the text?","options":["To compare winter and summer weather in several deserts","To explain why the Sonoran Desert receives less rain than other deserts","To correct a common assumption about deserts by describing one that supports abundant plant life","To argue that deserts should be protected from development"],"answer":2,"explain":"The text opens with what \"many people think\" and then shows a desert that does not match it."},{"id":"rw-tsp-2","section":"rw","domain":"cs","skill":"tsp","level":1,"type":"mc","passage":"Mira had rehearsed the speech for a week. Now, standing before the class, she found that every sentence had slipped away. She looked at her notes, then at the window, then at her notes again.","question":"Which choice best states the main purpose of the text?","options":["To show that a character is bored by her classmates","To explain how a character memorized a speech","To portray a character's nervousness at a moment she had prepared for","To describe a classroom from a teacher's point of view"],"answer":2,"explain":"The forgotten sentences and the restless glances show nerves despite a week of practice."},{"id":"rw-tsp-5","section":"rw","domain":"cs","skill":"tsp","level":2,"type":"mc","passage":"For decades, textbooks described the octopus as a solitary animal. Then divers off the coast of Australia found a site where a dozen or more octopuses live side by side, signaling to one another with changes in color. The discovery has led some biologists to ask whether solitude is a matter of circumstance rather than nature.","question":"Which choice best describes the overall structure of the text?","options":["It presents a long-held view, describes a finding that complicates it, and notes a question the finding raises.","It describes a finding, explains the method used to obtain it, and argues that the method is flawed.","It presents two competing views and explains why neither can be tested.","It introduces a species, lists its features, and compares it with a related species."],"answer":0,"explain":"View (\"for decades\"), then finding (\"then divers\"), then the question it raises."},{"id":"rw-tsp-6","section":"rw","domain":"cs","skill":"tsp","level":2,"type":"mc","passage":"Before drafting a novel, the writer fills a notebook with details that may never appear in the book: what a character keeps in her pockets, which songs she hums. Readers never see these pages, the writer says, but they feel them, the way a visitor senses a well-built foundation without seeing it.","question":"Which choice best states the main purpose of the text?","options":["To explain how a writer's unseen preparation shapes the finished work","To argue that novels should include more everyday details","To criticize writers who rely on notebooks","To describe the plot of a particular novel"],"answer":0,"explain":"The foundation comparison makes the point: readers feel the hidden groundwork."},{"id":"rw-tsp-9","section":"rw","domain":"cs","skill":"tsp","level":3,"type":"mc","passage":"Some economists treat a nation's rising output as proof of rising well-being. Yet output counts the cost of cleaning up an oil spill as growth while ignoring the unpaid work of raising children. A measure so indifferent to what is being produced, critics argue, cannot tell us whether life is improving.","question":"Which choice best describes the function of the second sentence in the text as a whole?","options":["It concedes that the view in the first sentence is largely correct.","It supplies examples that show a limitation of the measure mentioned in the first sentence.","It defines a term introduced in the first sentence.","It describes how the measure in the first sentence was developed."],"answer":1,"explain":"The oil spill and child-raising examples show what output gets wrong."},{"id":"rw-ctc-1","section":"rw","domain":"cs","skill":"ctc","level":1,"type":"mc","passage":"Text 1\nRemote work harms creativity, some managers claim, because new ideas arise from chance conversations in hallways.\n\nText 2\nA study of engineering teams found that those working remotely produced as many new product ideas as office-based teams, provided they held regular unstructured video calls.","question":"Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1?","options":["By agreeing that remote teams produce fewer ideas","By arguing that new product ideas are a poor measure of creativity","By suggesting that the benefit of chance conversations can be achieved in other ways","By claiming that hallway conversations never produce ideas"],"answer":2,"explain":"Text 2 reports equal output when remote teams hold unstructured calls, a substitute for hallway talk."},{"id":"rw-ctc-2","section":"rw","domain":"cs","skill":"ctc","level":1,"type":"mc","passage":"Text 1\nPopular films show dinosaurs as giant scaly lizards, and many viewers assume this picture is accurate.\n\nText 2\nSince the 1990s, paleontologists have uncovered fossils of numerous dinosaur species that preserve clear impressions of feathers.","question":"Based on the texts, how would the author of Text 2 most likely respond to the assumption described in Text 1?","options":["By noting that dinosaur films have become more popular since the 1990s","By arguing that scales and feathers cannot be told apart in fossils","By pointing out that fossil evidence shows many dinosaurs had feathers","By agreeing that the popular picture needs no revision"],"answer":2,"explain":"Feathered fossils contradict the all-scaly picture."},{"id":"rw-ctc-3","section":"rw","domain":"cs","skill":"ctc","level":2,"type":"mc","passage":"Text 1\nRaising the minimum wage, one economist argues, inevitably reduces employment, since businesses respond to higher labor costs by hiring fewer workers.\n\nText 2\nResearchers compared neighboring counties on either side of a state border after one state raised its minimum wage. They found no measurable difference in the number of restaurant jobs.","question":"Based on the texts, how would the researchers in Text 2 most likely respond to the argument in Text 1?","options":["By agreeing that higher wages always lead to fewer jobs","By arguing that restaurants should not be studied","By claiming that minimum wages have no effect on workers' pay","By citing evidence that the predicted effect does not always occur"],"answer":3,"explain":"Text 1 says \"inevitably\"; Text 2 offers a case where job numbers did not differ."},{"id":"rw-ctc-4","section":"rw","domain":"cs","skill":"ctc","level":2,"type":"mc","passage":"Text 1\nA translation should stay as close to the original words as possible, one critic insists; the translator's task is accuracy, not artistry.\n\nText 2\nA translator of poetry writes that a word-for-word version of a poem \"delivers the words and loses the poem,\" because rhythm and sound carry as much meaning as vocabulary does.","question":"Based on the texts, how would the translator in Text 2 most likely regard the approach described in Text 1?","options":["As ideal for poetry, because it preserves rhythm","As suitable only for poems that do not rhyme","As impossible, because no words can ever be translated","As inadequate for poetry, because it sacrifices qualities essential to the original"],"answer":3,"explain":"The translator says a word-for-word version \"loses the poem\"."},{"id":"rw-ctc-6","section":"rw","domain":"cs","skill":"ctc","level":3,"type":"mc","passage":"Text 1\nSleep researchers long held that memories are strengthened mainly during deep, slow-wave sleep.\n\nText 2\nIn recent experiments, volunteers whose REM sleep was interrupted, but whose deep sleep was left intact, performed markedly worse at recalling skills they had learned the previous day.","question":"Based on the texts, how would the researchers in Text 2 most likely respond to the view described in Text 1?","options":["By suggesting that skills cannot be learned in a single day","By confirming that deep sleep alone accounts for memory","By claiming that sleep has no effect on memory","By arguing that it gives too little weight to another stage of sleep"],"answer":3,"explain":"Recall suffered when only REM sleep was disturbed, so REM sleep matters too."},{"id":"rw-cid-1","section":"rw","domain":"ii","skill":"cid","level":1,"type":"mc","passage":"Tea plants grow best on well-drained slopes with heavy rainfall. The hills of Sylhet, in northeastern Bangladesh, offer both, which is why the region has been a center of tea growing since the nineteenth century.","question":"Which choice best states the main idea of the text?","options":["Sylhet produces more tea than any other region in the world.","Tea grows best in flat, dry regions.","Tea was first discovered in Sylhet.","Sylhet's geography makes it well suited to growing tea."],"answer":3,"explain":"The text links what tea needs (slopes, rain) to what Sylhet has."},{"id":"rw-cid-2","section":"rw","domain":"ii","skill":"cid","level":1,"type":"mc","passage":"The Arctic tern migrates from the Arctic to the Antarctic and back each year, a round trip of roughly 70,000 kilometers. Because it spends summer in each hemisphere, it sees more daylight than any other animal.","question":"According to the text, why does the Arctic tern see more daylight than any other animal?","options":["It migrates only during the day.","It sleeps less than other birds.","It flies faster than other birds.","It experiences summer in both hemispheres."],"answer":3,"explain":"The last sentence gives the reason directly: \"Because it spends summer in each hemisphere\"."},{"id":"rw-cid-5","section":"rw","domain":"ii","skill":"cid","level":2,"type":"mc","passage":"The first photographs of single snowflakes were taken in 1885 by Wilson Bentley, a Vermont farmer who attached a camera to a microscope. Over his life he captured more than 5,000 images. Scientists of his day paid little attention, but his pictures later became a foundation for the study of ice crystals.","question":"Which choice best states the main idea of the text?","options":["Bentley was celebrated by scientists throughout his life.","Snowflakes look identical under a microscope.","Photographing snowflakes requires expensive equipment.","An amateur's patient work, overlooked at first, proved scientifically valuable."],"answer":3,"explain":"A farmer, ignored at first, whose images later became a foundation for research."},{"id":"rw-cid-6","section":"rw","domain":"ii","skill":"cid","level":2,"type":"mc","passage":"Mangrove trees in the Sundarbans grow in mud that is flooded twice a day and holds little oxygen. Many species therefore send up pencil-like roots that rise above the mud and take in air directly.","question":"According to the text, what purpose do the upward-growing roots serve?","options":["They remove salt from seawater.","They anchor the trees against storms.","They store fresh water for dry seasons.","They allow the trees to obtain oxygen that the mud lacks."],"answer":3,"explain":"The mud \"holds little oxygen\", so the roots \"take in air directly\"."},{"id":"rw-cid-9","section":"rw","domain":"ii","skill":"cid","level":3,"type":"mc","passage":"Medieval cathedral builders did not work from complete plans. Construction often lasted more than a century, and each generation of masons adjusted the design to new tastes, new techniques, and whatever funds were available. The unity that visitors admire today is frequently the result of later restorers smoothing over those differences.","question":"Which choice best states the main idea of the text?","options":["Cathedrals built quickly are more unified than those built slowly.","The apparent consistency of many cathedrals conceals a long, improvised building process.","Restorers have damaged most medieval cathedrals.","Medieval masons followed detailed plans drawn before construction began."],"answer":1,"explain":"Generations changed the design; the unity seen today was often added later."},{"id":"rw-coe-1","section":"rw","domain":"ii","skill":"coe","level":1,"type":"mc","passage":"Researchers hypothesized that street lighting reduces the number of moths that visit flowers at night.","question":"Which finding, if true, would most directly support the researchers' hypothesis?","options":["Bees visited both groups of flowers equally during the day.","Flowers under streetlights were taller than flowers in dark areas.","Flowers under streetlights received fewer moth visits than flowers in dark areas nearby.","Moths are more numerous in summer than in winter."],"answer":2,"explain":"Only this finding compares moth visits with and without lighting."},{"id":"rw-coe-2","section":"rw","domain":"ii","skill":"coe","level":1,"type":"mc","passage":"A student grew bean seedlings under different amounts of daily light for four weeks and concluded that more light led to more growth. For example, ______","table":{"head":["Daily light","Growth after 4 weeks"],"rows":[["4 hours","6 cm"],["8 hours","11 cm"],["12 hours","15 cm"]]},"question":"Which choice most effectively uses data from the table to complete the statement?","options":["all of the seedlings were grown for four weeks.","seedlings given 4 hours of light grew 15 cm.","seedlings given 12 hours of light grew 15 cm, while those given 4 hours grew 6 cm.","seedlings given 8 hours of light grew 6 cm."],"answer":2,"explain":"The correct choice reads the table accurately and shows more light with more growth."},{"id":"rw-coe-6","section":"rw","domain":"ii","skill":"coe","level":2,"type":"mc","passage":"Ecologists proposed that the return of wolves to a valley changed where elk graze: elk now avoid riverbanks, where they are easily ambushed, which allows young willows there to grow.","question":"Which finding, if true, would most directly support the ecologists' proposal?","options":["Willows along riverbanks grew taller after wolves returned, while willows on open hillsides, where elk still graze, did not.","The number of elk in the valley was the same before and after wolves returned.","Wolves in the valley were observed hunting deer as well as elk.","Rainfall increased after wolves returned, and willows grew taller everywhere."],"answer":0,"explain":"Growth only where elk now avoid grazing is what the proposal predicts."},{"id":"rw-coe-7","section":"rw","domain":"ii","skill":"coe","level":2,"type":"mc","passage":"A survey asked adults in one city how they prefer to commute. The results suggest that the preference for cycling declines with age: ______","table":{"head":["Age group","Bus","Bicycle","Car"],"rows":[["18 to 29","45%","30%","25%"],["30 to 49","35%","15%","50%"],["50 and older","30%","5%","65%"]]},"question":"Which choice most effectively uses data from the table to complete the statement?","options":["30% of respondents aged 18 to 29 preferred cycling, compared with 15% of those aged 30 to 49 and 5% of those 50 and older.","45% of respondents aged 18 to 29 preferred the bus, compared with 35% of those aged 30 to 49.","15% of respondents aged 18 to 29 preferred cycling.","65% of respondents aged 50 and older preferred to travel by car."],"answer":0,"explain":"Only this choice gives the cycling figures across all three age groups, and gives them correctly."},{"id":"rw-coe-11","section":"rw","domain":"ii","skill":"coe","level":3,"type":"mc","passage":"Linguists hypothesize that a child learns a word faster when an adult names an object the child is already looking at, rather than redirecting the child's attention to something new.","question":"Which finding, if true, would most directly support the linguists' hypothesis?","options":["Toddlers learned more new words from parents who named whatever the toddler was holding than from parents who introduced a different toy before naming it.","Toddlers looked longer at brightly colored toys than at dull ones.","Toddlers who owned more toys knew more words.","Parents who spoke more words per hour had toddlers with larger vocabularies."],"answer":0,"explain":"It compares the two situations in the hypothesis. The amount of speech is a different question."},{"id":"rw-inf-1","section":"rw","domain":"ii","skill":"inf","level":1,"type":"mc","passage":"Karim counted his coins twice. There was enough for the bus fare or for the notebook he needed, but not for both. He put the coins back in his pocket and set off on foot, which suggests that ______","question":"Which choice most logically completes the text?","options":["he no longer needed the notebook.","he had lost some of his coins.","he chose to save his money for the notebook.","he had never ridden the bus."],"answer":2,"explain":"He could afford only one, kept the coins, and walked: the money is for the notebook."},{"id":"rw-inf-2","section":"rw","domain":"ii","skill":"inf","level":1,"type":"mc","passage":"Most birds in the park fly south by October. This year, however, the pond has not frozen, insects remain plentiful, and several species are still present in December. This suggests that the birds' departure depends ______","question":"Which choice most logically completes the text?","options":["at least partly on food and weather rather than on the date alone.","entirely on the length of the days.","on the age of the birds.","on the number of visitors to the park."],"answer":0,"explain":"With mild weather and food available, the birds stayed past their usual date."},{"id":"rw-inf-5","section":"rw","domain":"ii","skill":"inf","level":2,"type":"mc","passage":"A plant species grows on two islands. On the island with no grazing animals its leaves are soft; on the island with goats its leaves are tough and bitter. Seeds from both islands, grown side by side in one greenhouse, keep these differences. This suggests that the difference ______","question":"Which choice most logically completes the text?","options":["would disappear if the goats were removed for one season.","is inherited rather than produced directly by the conditions in which each plant grows.","is caused by the soil used in the greenhouse.","results from differences in rainfall between the islands."],"answer":1,"explain":"In identical conditions the difference remains, so it is carried in the seeds."},{"id":"rw-inf-6","section":"rw","domain":"ii","skill":"inf","level":2,"type":"mc","passage":"Reviewers praised the novelist's first book for its humor. Her second, a somber family history, sold poorly, and several reviews complained that it was \"not what readers expect from her.\" This reaction suggests that an author's early success can ______","question":"Which choice most logically completes the text?","options":["prove that humorous books are better than serious ones.","create expectations that make it harder for a different kind of work to be accepted.","guarantee strong sales for every later book.","discourage reviewers from reading later books."],"answer":1,"explain":"The complaint was about expectations, not about the quality of the second book."},{"id":"rw-inf-9","section":"rw","domain":"ii","skill":"inf","level":3,"type":"mc","passage":"Glaciologists drilling in Greenland found that ice layers from an unusually warm ancient period contain more dust than layers from colder periods nearby in the record. Since dust is carried onto the ice mainly from exposed ground, the finding suggests that during the warm period ______","question":"Which choice most logically completes the text?","options":["winds over Greenland stopped blowing.","less ground was exposed than in colder periods.","more land in the region was free of ice and snow.","the ice sheet was thicker than it is today."],"answer":2,"explain":"More dust means more exposed ground, which fits a warmer period."},{"id":"rw-bnd-1","section":"rw","domain":"sec","skill":"bnd","level":1,"type":"mc","passage":"The Padma Bridge opened to traffic in ______ connects the southwest of Bangladesh to the capital, Dhaka.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["2022. It","2022, it","2022 it","2022 and it,"],"answer":0,"explain":"Two complete sentences need a full stop (or a semicolon) between them. A comma alone is a comma splice."},{"id":"rw-bnd-2","section":"rw","domain":"sec","skill":"bnd","level":1,"type":"mc","passage":"The workshop teaches three ______ and bookbinding.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["crafts: papermaking, printing,","crafts, papermaking, printing,","crafts; papermaking, printing,","crafts: papermaking; printing;"],"answer":0,"explain":"A colon introduces the list after a complete statement; simple list items are separated by commas."},{"id":"rw-bnd-6","section":"rw","domain":"sec","skill":"bnd","level":2,"type":"mc","passage":"The first prototype failed within ______ the second ran for a year without repair.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["hours however,","hours, however;","hours, however,","hours; however,"],"answer":3,"explain":"\"However\" cannot join two sentences with commas alone. Use a semicolon before it and a comma after."},{"id":"rw-bnd-7","section":"rw","domain":"sec","skill":"bnd","level":2,"type":"mc","passage":"The expedition had one ______ to map the cave before the rainy season flooded it.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["goal. To","goal, being","goal;","goal:"],"answer":3,"explain":"A colon after a complete statement introduces what the goal is. A semicolon would need a full sentence after it."},{"id":"rw-bnd-12","section":"rw","domain":"sec","skill":"bnd","level":3,"type":"mc","passage":"In 1952, students in Dhaka marched to defend their ______ a movement now commemorated worldwide as International Mother Language Day.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["language. Launching","language launching","language; launching","language, launching"],"answer":3,"explain":"\"Launching a movement...\" is not a full sentence, so it attaches with a comma. A full stop or semicolon would leave a fragment."},{"id":"rw-fss-1","section":"rw","domain":"sec","skill":"fss","level":1,"type":"mc","passage":"The box of old letters ______ on the top shelf.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["are sitting","sits","have sat","sit"],"answer":1,"explain":"The subject is \"box\" (singular), not \"letters\", so the verb is \"sits\"."},{"id":"rw-fss-2","section":"rw","domain":"sec","skill":"fss","level":1,"type":"mc","passage":"Last year, the choir ______ in three cities; this year it will visit five.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["has been performing","will perform","performed","performs"],"answer":2,"explain":"\"Last year\" is a finished time, so use the simple past."},{"id":"rw-fss-7","section":"rw","domain":"sec","skill":"fss","level":2,"type":"mc","passage":"The results of the three-year study, published last month in a leading journal, ______ that the treatment is effective.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["suggest","has suggested","is suggesting","suggests"],"answer":0,"explain":"The subject is \"results\" (plural). Ignore the words between the subject and the verb."},{"id":"rw-fss-8","section":"rw","domain":"sec","skill":"fss","level":2,"type":"mc","passage":"Walking through the old market, ______","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["the traveler noticed the smell of cardamom everywhere.","there was a smell of cardamom that the traveler noticed everywhere.","the smell of cardamom was everywhere the traveler noticed.","the smell of cardamom was noticed by the traveler everywhere."],"answer":0,"explain":"The opening phrase describes whoever was walking, so \"the traveler\" must come straight after the comma."},{"id":"rw-fss-13","section":"rw","domain":"sec","skill":"fss","level":3,"type":"mc","passage":"The mural, ______ by a group of local teenagers over a single summer, now covers the entire north wall of the station.","question":"Which choice completes the text so that it conforms to the conventions of Standard English?","options":["they painted","was painted","painted","is painted"],"answer":2,"explain":"The main verb is \"covers\". Between the commas only a describing phrase fits: \"painted by...\"."},{"id":"rw-trn-1","section":"rw","domain":"eoi","skill":"trn","level":1,"type":"mc","passage":"The trail is only two kilometers long. ______ it climbs so steeply that most hikers need over an hour to finish it.","question":"Which choice completes the text with the most logical transition?","options":["Therefore,","However,","For example,","Similarly,"],"answer":1,"explain":"A short trail that takes a long time is a contrast: \"However\"."},{"id":"rw-trn-2","section":"rw","domain":"eoi","skill":"trn","level":1,"type":"mc","passage":"The reservoir fell to a record low this summer. ______ the city asked residents to limit their use of water.","question":"Which choice completes the text with the most logical transition?","options":["Nevertheless,","As a result,","For instance,","In contrast,"],"answer":1,"explain":"The low reservoir caused the request, so the link is cause and effect."},{"id":"rw-trn-5","section":"rw","domain":"eoi","skill":"trn","level":2,"type":"mc","passage":"The potter first shapes the clay on a wheel and lets it dry for a week. ______ she fires it in a kiln at over 1,000 degrees.","question":"Which choice completes the text with the most logical transition?","options":["In other words,","Then,","Instead,","Likewise,"],"answer":1,"explain":"The sentences describe steps in order: first..., then...."},{"id":"rw-trn-6","section":"rw","domain":"eoi","skill":"trn","level":2,"type":"mc","passage":"The new vaccine is expensive to produce. ______ health officials argue that it will save money over time by preventing costly hospital stays.","question":"Which choice completes the text with the most logical transition?","options":["Similarly,","Nevertheless,","Consequently,","For instance,"],"answer":1,"explain":"Despite the cost, officials support it: a concession followed by a contrast."},{"id":"rw-trn-10","section":"rw","domain":"eoi","skill":"trn","level":3,"type":"mc","passage":"The reform was expected to shorten court delays. ______ the average wait for a trial rose from eight months to eleven.","question":"Which choice completes the text with the most logical transition?","options":["Likewise,","Accordingly,","On the contrary,","Specifically,"],"answer":2,"explain":"The result was the opposite of what was expected."},{"id":"rw-syn-1","section":"rw","domain":"eoi","skill":"syn","level":1,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• The Sundarbans is the largest mangrove forest in the world.\n• It lies across Bangladesh and India.\n• It is home to the Bengal tiger.\n• The Bangladesh part became a UNESCO World Heritage Site in 1997.","question":"The student wants to emphasize the size of the Sundarbans. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["The Sundarbans, which lies across Bangladesh and India, is the largest mangrove forest in the world.","The Sundarbans is home to the Bengal tiger.","The Bangladesh part of the Sundarbans became a UNESCO World Heritage Site in 1997.","The Sundarbans lies across two countries, Bangladesh and India."],"answer":0,"explain":"Only this choice includes the fact about size (\"largest... in the world\")."},{"id":"rw-syn-2","section":"rw","domain":"eoi","skill":"syn","level":1,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• Venus rotates once every 243 Earth days.\n• Jupiter rotates once about every 10 hours.\n• Venus is a rocky planet.\n• Jupiter is a gas giant.","question":"The student wants to contrast how fast the two planets rotate. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["While Venus takes 243 Earth days to rotate once, Jupiter does so in about 10 hours.","Venus is a rocky planet, whereas Jupiter is a gas giant.","Both Venus and Jupiter rotate.","Jupiter, a gas giant, rotates about once every 10 hours."],"answer":0,"explain":"A contrast of rotation needs both rotation times side by side."},{"id":"rw-syn-4","section":"rw","domain":"eoi","skill":"syn","level":2,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• Researchers studied 200 office workers for six weeks.\n• Half were given desks near windows.\n• Workers near windows slept 46 minutes longer per night on average.\n• Sleep was measured with wrist monitors.","question":"The student wants to summarize the main finding of the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["In a six-week study of office workers, those seated near windows slept an average of 46 minutes longer per night than those who were not.","Wrist monitors can be used to measure how long people sleep.","Researchers studied 200 office workers, half of whom were given desks near windows.","Office workers took part in a six-week study about sleep."],"answer":0,"explain":"The finding is the result (46 minutes more sleep), not the method."},{"id":"rw-syn-5","section":"rw","domain":"eoi","skill":"syn","level":2,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• Bamboo and steel are both used for scaffolding in construction.\n• Bamboo scaffolding is lighter than steel.\n• Bamboo scaffolding can be put up about six times faster.\n• Steel scaffolding lasts longer.","question":"The student wants to emphasize an advantage of steel scaffolding. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["Bamboo scaffolding is lighter than steel scaffolding.","Both bamboo and steel are used for scaffolding in construction.","Bamboo scaffolding can be put up about six times faster than steel.","Although bamboo scaffolding is lighter and faster to put up, steel scaffolding lasts longer."],"answer":3,"explain":"The only advantage of steel in the notes is that it lasts longer."},{"id":"rw-syn-7","section":"rw","domain":"eoi","skill":"syn","level":3,"type":"mc","passage":"While researching a topic, a student has taken the following notes:\n• A team of chemists is developing a plastic made from seaweed.\n• Their aim is to replace packaging that takes centuries to break down.\n• The seaweed plastic dissolves in water within weeks.\n• The team tested 30 formulas before finding one that was strong enough.","question":"The student wants to emphasize the aim of the research. Which choice most effectively uses relevant information from the notes to accomplish this goal?","options":["The seaweed plastic dissolves in water within weeks.","After testing 30 formulas, the team found one that was strong enough.","A team of chemists tested 30 formulas of a seaweed plastic that dissolves in water.","Hoping to replace packaging that takes centuries to break down, a team of chemists is developing a plastic made from seaweed."],"answer":3,"explain":"The aim is why they are doing it: to replace long-lasting packaging."},{"id":"m-lin1-1-1","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"If 2x + 1 = 3, what is the value of x?","options":["−1","0","1","2"],"answer":2,"explain":"Take 1 from both sides: 2x = 2. Divide by 2: x = 1."},{"id":"m-lin1-1-2","section":"math","domain":"alg","skill":"lin1","level":1,"type":"mc","question":"If 3x − 4 = 29, what is the value of x?","options":["−11","25/3","11","33"],"answer":2,"explain":"Add 4 to both sides: 3x = 33. Divide by 3: x = 11."},{"id":"m-lin1-2-1","section":"math","domain":"alg","skill":"lin1","level":2,"type":"mc","question":"2(x + 3) = 5x + 21\n\nWhat value of x satisfies the equation above?","options":["−9","−6","−5","5"],"answer":2,"explain":"Expand the left side: 2x + 6 = 5x + 21. Collect terms: −3x = 15, so x = −5."},{"id":"m-lin1-2-2","section":"math","domain":"alg","skill":"lin1","level":2,"type":"mc","question":"4(x − 1) = −2x − 28\n\nWhat value of x satisfies the equation above?","options":["−16/3","−9/2","−4","4"],"answer":2,"explain":"Expand the left side: 4x − 4 = −2x − 28. Collect terms: 6x = −24, so x = −4."},{"id":"m-lin1-3-1","section":"math","domain":"alg","skill":"lin1","level":3,"type":"spr","question":"x/2 + x/7 = 18\n\nWhat value of x satisfies the equation above?","accept":["28"],"values":[28],"explain":"Multiply every term by 14: 7x + 2x = 252, so 9x = 252 and x = 28."},{"id":"m-lin2-1-1","section":"math","domain":"alg","skill":"lin2","level":1,"type":"mc","question":"In the xy-plane, a line passes through the points (−5, 5) and (0, 1). What is the slope of the line?","options":["−5/4","−4/5","4/5","5/4"],"answer":1,"explain":"Slope = change in y over change in x = (1 − 5) / (0 − (−5)) = −4/5."},{"id":"m-lin2-1-2","section":"math","domain":"alg","skill":"lin2","level":1,"type":"mc","question":"In the xy-plane, a line passes through the points (1, −2) and (2, 0). What is the slope of the line?","options":["−2","−1/2","1/2","2"],"answer":3,"explain":"Slope = change in y over change in x = (0 − (−2)) / (2 − 1) = 2/1 = 2."},{"id":"m-lin2-2-1","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"A line in the xy-plane has a slope of −2 and passes through the point (−2, 7). Which equation represents the line?","options":["y = −2x + 11","y = 3x − 2","y = −2x + 3","y = −2x + 7"],"answer":2,"explain":"Use y = mx + b with m = −2: 7 = −2(−2) + b, so b = 3."},{"id":"m-lin2-2-2","section":"math","domain":"alg","skill":"lin2","level":2,"type":"mc","question":"A line in the xy-plane has a slope of −3 and passes through the point (−1, −5). Which equation represents the line?","options":["y = −3x − 2","y = −3x − 5","y = −3x − 8","y = −8x − 3"],"answer":2,"explain":"Use y = mx + b with m = −3: −5 = −3(−1) + b, so b = −8."},{"id":"m-lin2-3-1","section":"math","domain":"alg","skill":"lin2","level":3,"type":"mc","question":"Line k is defined by 4x + 5y = 9. Line j is perpendicular to line k in the xy-plane. What is the slope of line j?","options":["4/5","5/4","−5/4","−4/5"],"answer":1,"explain":"Solve for y: y = (−4/5)x + 9/5, so line k has slope −4/5. A perpendicular line has the negative reciprocal slope: 5/4."},{"id":"m-linf-1-1","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function f is defined by f(x) = 6x − 8. What is the value of f(4)?","options":["2","16","24","32"],"answer":1,"explain":"f(4) = 6(4) − 8 = 24 − 8 = 16."},{"id":"m-linf-1-2","section":"math","domain":"alg","skill":"linf","level":1,"type":"mc","question":"The function f is defined by f(x) = 7x − 2. What is the value of f(−4)?","options":["−30","−28","−26","1"],"answer":0,"explain":"f(−4) = 7(−4) − 2 = −28 − 2 = −30."},{"id":"m-linf-2-1","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"For the linear function f, f(1) = 8 and f(5) = 20. What is the value of f(10)?","options":["25","28","35","38"],"answer":2,"explain":"The slope is (20 − 8) / (5 − 1) = 3. From x = 5 to x = 10 the function changes by 3 × 5 = 15, giving 35."},{"id":"m-linf-2-2","section":"math","domain":"alg","skill":"linf","level":2,"type":"mc","question":"For the linear function f, f(1) = 3 and f(4) = −9. What is the value of f(6)?","options":["−21","−17","−7","−6"],"answer":1,"explain":"The slope is (−9 − 3) / (4 − 1) = −4. From x = 4 to x = 6 the function changes by −4 × 2 = −8, giving −17."},{"id":"m-linf-3-1","section":"math","domain":"alg","skill":"linf","level":3,"type":"spr","question":"For the linear function g, g(3) = 13 and g(7) = 29. The graph of y = g(x) in the xy-plane crosses the y-axis at (0, b). What is the value of b?","accept":["1"],"values":[1],"explain":"The slope is 4. Using g(3) = 13: 13 = 4(3) + b, so b = 1."},{"id":"m-sys-1-1","section":"math","domain":"alg","skill":"sys","level":1,"type":"mc","question":"x + y = 12\nx − y = −4\n\nThe solution to the system above is (x, y). What is the value of x?","options":["−4","4","8","12"],"answer":1,"explain":"Add the equations: 2x = 8, so x = 4."},{"id":"m-sys-1-2","section":"math","domain":"alg","skill":"sys","level":1,"type":"mc","question":"x + y = 7\nx − y = −9\n\nThe solution to the system above is (x, y). What is the value of x?","options":["−9","−1","7","8"],"answer":1,"explain":"Add the equations: 2x = −2, so x = −1."},{"id":"m-sys-2-1","section":"math","domain":"alg","skill":"sys","level":2,"type":"mc","question":"3x − y = 8\n2x + y = 17\n\nIf (x, y) is the solution to the system above, what is the value of x + y?","options":["−2","5","7","12"],"answer":3,"explain":"Solving the system gives x = 5 and y = 7, so x + y = 12."},{"id":"m-sys-2-2","section":"math","domain":"alg","skill":"sys","level":2,"type":"mc","question":"2x + 3y = 19\nx − 2y = −1\n\nIf (x, y) is the solution to the system above, what is the value of x + y?","options":["2","3","5","8"],"answer":3,"explain":"Solving the system gives x = 5 and y = 3, so x + y = 8."},{"id":"m-sys-3-1","section":"math","domain":"alg","skill":"sys","level":3,"type":"mc","question":"2x + 3y = 4\nkx + 6y = 13\n\nIn the system above, k is a constant. The system has no solution. What is the value of k?","options":["1","2","4","6"],"answer":2,"explain":"No solution means the lines are parallel: the left sides are multiples of each other but the right sides are not. 6y is 2 times 3y, so k = 2 × 2 = 4 (and 13 is not 2 × 4)."},{"id":"m-ineq-1-1","section":"math","domain":"alg","skill":"ineq","level":1,"type":"mc","question":"Which of the following describes all solutions to 3x + 9 > −6?","options":["x > 5","x > −5","x < 5","x < −5"],"answer":1,"explain":"Take 9 from both sides: 3x > −15. Divide by 3: x > −5."},{"id":"m-ineq-1-2","section":"math","domain":"alg","skill":"ineq","level":1,"type":"mc","question":"Which of the following describes all solutions to 6x + 7 > 55?","options":["x > 8","x < 8","x < −8","x > −8"],"answer":0,"explain":"Take 7 from both sides: 6x > 48. Divide by 6: x > 8."},{"id":"m-ineq-2-1","section":"math","domain":"alg","skill":"ineq","level":2,"type":"mc","question":"Which of the following describes all solutions to −5x + 9 > −31?","options":["x < 8","x > 8","x > −8","x < −8"],"answer":0,"explain":"Take 9 from both sides: −5x > −40. Dividing by a negative number reverses the sign: x < 8."},{"id":"m-ineq-2-2","section":"math","domain":"alg","skill":"ineq","level":2,"type":"mc","question":"Which of the following describes all solutions to −3x + 1 > −2?","options":["x < −1","x > −1","x > 1","x < 1"],"answer":3,"explain":"Take 1 from both sides: −3x > −3. Dividing by a negative number reverses the sign: x < 1."},{"id":"m-ineq-3-1","section":"math","domain":"alg","skill":"ineq","level":3,"type":"mc","question":"y > 2x + 1\ny ≤ −x + 5\n\nWhich point (x, y) is a solution to the system of inequalities above?","options":["(4, 6)","(1, 5)","(−1, −3)","(−2, 4)"],"answer":3,"explain":"Test each point in both inequalities. For (−2, 4): 4 > −3 and 4 ≤ 7, so both hold. Each other point fails at least one."},{"id":"m-eqx-1-1","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (x + 4)(x + 2)?","options":["x² + 6x + 6","x² + 6x + 8","x² + 8","x² + 8x + 6"],"answer":1,"explain":"Multiply each term: x² + 2x + 4x + 8 = x² + 6x + 8."},{"id":"m-eqx-1-2","section":"math","domain":"adv","skill":"eqx","level":1,"type":"mc","question":"Which expression is equivalent to (x + 7)(x − 5)?","options":["x² − 35x + 2","x² + 2x + 2","x² + 2x − 35","x² − 35"],"answer":2,"explain":"Multiply each term: x² − 5x + 7x − 35 = x² + 2x − 35."},{"id":"m-eqx-2-1","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"Which expression is equivalent to x² − 12x + 32?","options":["(x − 8)(x − 4)","(x + 8)(x + 4)","(x − 8)(x + 4)","(x + 32)(x + 1)"],"answer":0,"explain":"Find two numbers that multiply to 32 and add to −12: −8 and −4. So the expression is (x − 8)(x − 4)."},{"id":"m-eqx-2-2","section":"math","domain":"adv","skill":"eqx","level":2,"type":"mc","question":"Which expression is equivalent to x² + x − 56?","options":["(x − 7)(x − 8)","(x + 7)(x − 8)","(x − 7)(x + 8)","(x − 56)(x + 1)"],"answer":2,"explain":"Find two numbers that multiply to −56 and add to 1: −7 and 8. So the expression is (x − 7)(x + 8)."},{"id":"m-eqx-3-1","section":"math","domain":"adv","skill":"eqx","level":3,"type":"mc","question":"Which expression is equivalent to (3x + 2)² − (3x − 2)²?","options":["8","0","18x² + 8","24x"],"answer":3,"explain":"Expand both squares: (9x² + 12x + 4) − (9x² − 12x + 4). The x² terms and the constants cancel, leaving 24x."},{"id":"m-nleq-1-1","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"x² + 6x − 27 = 0\n\nWhat is the positive solution to the equation above?","accept":["3"],"values":[3],"explain":"Factor: (x − 3)(x + 9) = 0, so x = 3 or x = −9. The positive solution is 3."},{"id":"m-nleq-1-2","section":"math","domain":"adv","skill":"nleq","level":1,"type":"spr","question":"x² + 7x − 18 = 0\n\nWhat is the positive solution to the equation above?","accept":["2"],"values":[2],"explain":"Factor: (x − 2)(x + 9) = 0, so x = 2 or x = −9. The positive solution is 2."},{"id":"m-nleq-2-1","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to 4x² − 10x − 6 = 0?","options":["−3/2","5/2","−5/2","3/2"],"answer":1,"explain":"For ax² + bx + c = 0 the solutions add up to −b/a = 5/2. (Here b² − 4ac is positive, so there are two real solutions.)"},{"id":"m-nleq-2-2","section":"math","domain":"adv","skill":"nleq","level":2,"type":"mc","question":"What is the sum of the solutions to 4x² + x − 2 = 0?","options":["1/4","1/2","−1/2","−1/4"],"answer":3,"explain":"For ax² + bx + c = 0 the solutions add up to −b/a = −1/4. (Here b² − 4ac is positive, so there are two real solutions.)"},{"id":"m-nleq-3-1","section":"math","domain":"adv","skill":"nleq","level":3,"type":"spr","question":"x² − 12x + c = 0\n\nIn the equation above, c is a constant. The equation has exactly one real solution. What is the value of c?","accept":["36"],"values":[36],"explain":"One real solution means the discriminant is zero: (12)² − 4c = 0, so 4c = 144 and c = 36."},{"id":"m-nlf-1-1","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function f is defined by f(x) = −x² + 2x − 6. What is the value of f(−3)?","options":["−21","−9","−6","−3"],"answer":0,"explain":"f(−3) = −1(9) − 6 − 6 = −21. Remember that (−3)² = 9."},{"id":"m-nlf-1-2","section":"math","domain":"adv","skill":"nlf","level":1,"type":"mc","question":"The function f is defined by f(x) = 2x² + 6x + 7. What is the value of f(4)?","options":["−1","15","47","63"],"answer":3,"explain":"f(4) = 2(16) + 24 + 7 = 63. Remember that (4)² = 16."},{"id":"m-nlf-2-1","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function g is defined by g(x) = −2(x − 5)² − 6. For what value of x does g(x) reach its maximum?","options":["−6","−5","5","6"],"answer":2,"explain":"The squared term is zero when x = 5, and for every other x it makes g smaller. So the maximum is at x = 5."},{"id":"m-nlf-2-2","section":"math","domain":"adv","skill":"nlf","level":2,"type":"mc","question":"The function f is defined by f(x) = 2(x − 4)² + 8. What is the minimum value of f?","options":["−8","−4","4","8"],"answer":3,"explain":"A square is never negative, so (x − 4)² is smallest (zero) when x = 4. The minimum value is then 8."},{"id":"m-nlf-3-1","section":"math","domain":"adv","skill":"nlf","level":3,"type":"mc","question":"The function f is defined by f(x) = x² − 4x + 8. What is the minimum value of f?","options":["2","4","8","12"],"answer":1,"explain":"Complete the square: f(x) = (x − 2)² + 4. The minimum is 4, at x = 2."},{"id":"m-rate-1-1","section":"math","domain":"psda","skill":"rate","level":1,"type":"mc","question":"A train travels 120 kilometres in 3 hours at a constant speed. At this speed, how many kilometres does it travel in 5 hours?","options":["80","125","200","600"],"answer":2,"explain":"Speed = 120 / 3 = 40 km per hour. In 5 hours: 40 × 5 = 200 km."},{"id":"m-rate-1-2","section":"math","domain":"psda","skill":"rate","level":1,"type":"mc","question":"A train travels 180 kilometres in 4 hours at a constant speed. At this speed, how many kilometres does it travel in 6 hours?","options":["90","186","270","1080"],"answer":2,"explain":"Speed = 180 / 4 = 45 km per hour. In 6 hours: 45 × 6 = 270 km."},{"id":"m-rate-2-1","section":"math","domain":"psda","skill":"rate","level":2,"type":"mc","question":"A printer prints 24 pages per minute. How many hours does it take to print 1,080 pages?","options":["2/5","3/4","18","45"],"answer":1,"explain":"1,080 / 24 = 45 minutes, and 45 minutes is 3/4 hours."},{"id":"m-rate-2-2","section":"math","domain":"psda","skill":"rate","level":2,"type":"mc","question":"A car travels at a constant speed of 90 kilometres per hour. What is its speed in metres per second? (1 kilometre = 1,000 metres)","options":["3/2","25","324","1500"],"answer":1,"explain":"90 km per hour = 90,000 metres per 3,600 seconds = 25 metres per second."},{"id":"m-rate-3-1","section":"math","domain":"psda","skill":"rate","level":3,"type":"mc","question":"A car uses 8 litres of fuel for every 100 kilometres. Fuel costs $1.25 per litre. What is the cost of the fuel for a 600-kilometre trip?","options":["$7.5","$48","$60","$120"],"answer":2,"explain":"Fuel used: 600 / 100 × 8 = 48 litres. Cost: 48 × $1.25 = $60.00."},{"id":"m-pct-1-1","section":"math","domain":"psda","skill":"pct","level":1,"type":"mc","question":"What is 40% of 160?","options":["64","96","400","640"],"answer":0,"explain":"40% of 160 = 0.4 × 160 = 64."},{"id":"m-pct-1-2","section":"math","domain":"psda","skill":"pct","level":1,"type":"mc","question":"What is 25% of 360?","options":["90","270","900","1440"],"answer":0,"explain":"25% of 360 = 0.25 × 360 = 90."},{"id":"m-pct-2-1","section":"math","domain":"psda","skill":"pct","level":2,"type":"mc","question":"The price of a jacket changed from $40 to $44. By what percent did the price increase?","options":["4%","9.1%","10%","15%"],"answer":2,"explain":"Change = 4. Compare it with the original price: 4 / 40 = 0.1 = 10%."},{"id":"m-pct-2-2","section":"math","domain":"psda","skill":"pct","level":2,"type":"mc","question":"The price of a jacket changed from $150 to $120. By what percent did the price decrease?","options":["20%","21%","25%","30%"],"answer":0,"explain":"Change = 30. Compare it with the original price: 30 / 150 = 0.2 = 20%."},{"id":"m-pct-3-1","section":"math","domain":"psda","skill":"pct","level":3,"type":"mc","question":"A shop raises the price of a lamp by 40% and later lowers the new price by 25%. Compared with the original price, what is the overall change?","options":["An increase of 15%","A decrease of 5%","An increase of 5%","An increase of 65%"],"answer":2,"explain":"Multiply the changes: 1.4 × 0.75 = 1.05. That is an increase of 5% from the original price."},{"id":"m-stat-1-1","section":"math","domain":"psda","skill":"stat","level":1,"type":"mc","question":"What is the mean of the data set 4, 28, 16, 24, 18, 6?","options":["16","18","24","96"],"answer":0,"explain":"Add the values: 96. Divide by 6: 16."},{"id":"m-stat-1-2","section":"math","domain":"psda","skill":"stat","level":1,"type":"mc","question":"What is the mean of the data set 26, 21, 25, 3, 18, 15?","options":["18","21","23","108"],"answer":0,"explain":"Add the values: 108. Divide by 6: 18."},{"id":"m-stat-2-1","section":"math","domain":"psda","skill":"stat","level":2,"type":"spr","question":"The mean of five numbers is 17. Four of the numbers are 7, 6, 27, 19. What is the fifth number?","accept":["26"],"values":[26],"explain":"The five numbers add up to 5 × 17 = 85. The four given numbers add up to 59, so the fifth is 85 − 59 = 26."},{"id":"m-stat-2-2","section":"math","domain":"psda","skill":"stat","level":2,"type":"spr","question":"The mean of five numbers is 15. Four of the numbers are 16, 14, 27, 11. What is the fifth number?","accept":["7"],"values":[7],"explain":"The five numbers add up to 5 × 15 = 75. The four given numbers add up to 68, so the fifth is 75 − 68 = 7."},{"id":"m-stat-3-1","section":"math","domain":"psda","skill":"stat","level":3,"type":"mc","question":"The mean of 4 test scores is 14. When one more score is included, the mean of the 5 scores is 12. What is the score that was added?","options":["4","10","12","20"],"answer":0,"explain":"The first 4 scores total 4 × 14 = 56. All 5 total 5 × 12 = 60. The added score is 60 − 56 = 4."},{"id":"m-prob-1-1","section":"math","domain":"psda","skill":"prob","level":1,"type":"mc","question":"A bag holds 11 red, 7 blue and 4 green marbles. One marble is chosen at random. What is the probability that it is blue?","options":["7/22","1/2","2/11","7/15"],"answer":0,"explain":"There are 22 marbles and 7 are blue: 7/22."},{"id":"m-prob-1-2","section":"math","domain":"psda","skill":"prob","level":1,"type":"mc","question":"A bag holds 9 red, 10 blue and 8 green marbles. One marble is chosen at random. What is the probability that it is blue?","options":["10/27","1/3","8/27","10/17"],"answer":0,"explain":"There are 27 marbles and 10 are blue: 10/27."},{"id":"m-prob-2-1","section":"math","domain":"psda","skill":"prob","level":2,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If one of these students is chosen at random, what is the probability that the student walks to school?","options":["72/181","36/181","32/181","40/181"],"answer":0,"explain":"72 of the 181 students walk: 72/181.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","55","32","87"],["Grade 12","54","40","94"],["Total","109","72","181"]]}},{"id":"m-prob-2-2","section":"math","domain":"psda","skill":"prob","level":2,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If one of these students is chosen at random, what is the probability that the student walks to school?","options":["49/316","17/158","49/158","16/79"],"answer":2,"explain":"49 of the 158 students walk: 49/158.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","54","32","86"],["Grade 12","55","17","72"],["Total","109","49","158"]]}},{"id":"m-prob-3-1","section":"math","domain":"psda","skill":"prob","level":3,"type":"mc","question":"The table shows how the students in two grades at a school travel to school. If a Grade 12 student is chosen at random, what is the probability that the student walks to school?","options":["36/89","53/89","36/137","9/14"],"answer":0,"explain":"Look only at the Grade 12 row: 36 of the 89 Grade 12 students walk, so the probability is 36/89.","table":{"head":["","Bus","Walk","Total"],"rows":[["Grade 11","28","20","48"],["Grade 12","53","36","89"],["Total","81","56","137"]]}},{"id":"m-infr-1-1","section":"math","domain":"psda","skill":"infr","level":1,"type":"mc","question":"In a random sample of 50 students at a school, 10 said they cycle to school. The school has 1,000 students. Based on the sample, what is the best estimate of the number of students at the school who cycle to school?","options":["10","200","210","800"],"answer":1,"explain":"10/50 of the sample cycle. Apply the same share to everyone: 10/50 × 1,000 = 200."},{"id":"m-infr-1-2","section":"math","domain":"psda","skill":"infr","level":1,"type":"mc","question":"In a random sample of 40 students at a school, 14 said they cycle to school. The school has 1,200 students. Based on the sample, what is the best estimate of the number of students at the school who cycle to school?","options":["14","420","434","780"],"answer":1,"explain":"14/40 of the sample cycle. Apply the same share to everyone: 14/40 × 1,200 = 420."},{"id":"m-infr-2-1","section":"math","domain":"psda","skill":"infr","level":2,"type":"mc","question":"A survey of a random sample of adults in the city estimated that 42% plan to vote in the election, with a margin of error of 4%. Which conclusion is best supported?","options":["Exactly 42% of all adults in the city plan to vote in the election.","It is plausible that between 38% and 46% of all adults in the city plan to vote in the election.","At most 4% of all adults in the city gave an incorrect answer.","Between 38% and 46% of the people in the sample plan to vote in the election."],"answer":1,"explain":"A margin of error describes how far the true share for the whole population may be from the sample result: about 38% to 46%."},{"id":"m-infr-2-2","section":"math","domain":"psda","skill":"infr","level":2,"type":"mc","question":"A survey of a random sample of adults in the city estimated that 54% plan to vote in the election, with a margin of error of 4%. Which conclusion is best supported?","options":["At most 4% of all adults in the city gave an incorrect answer.","Between 50% and 58% of the people in the sample plan to vote in the election.","It is plausible that between 50% and 58% of all adults in the city plan to vote in the election.","Exactly 54% of all adults in the city plan to vote in the election."],"answer":2,"explain":"A margin of error describes how far the true share for the whole population may be from the sample result: about 50% to 58%."},{"id":"m-infr-3-1","section":"math","domain":"psda","skill":"infr","level":3,"type":"mc","question":"In a study, 60 volunteers were randomly assigned to two groups. One group drank green tea every day for a month and the other did not. At the end, the tea group had lower average blood pressure. Which conclusion is best supported?","options":["Drinking green tea caused lower blood pressure for the volunteers in the study.","Drinking green tea lowers blood pressure for all people.","People with low blood pressure tend to choose green tea.","No conclusion about cause can be drawn, because the groups were assigned at random."],"answer":0,"explain":"Random assignment allows a cause-and-effect conclusion, but only about the people in the study. Volunteers are not a random sample of everyone."},{"id":"m-area-1-1","section":"math","domain":"geo","skill":"area","level":1,"type":"mc","question":"A triangle has a base of 6 centimetres and a height of 9 centimetres. What is its area, in square centimetres?","options":["15","27","30","54"],"answer":1,"explain":"Area = ½ × base × height = ½ × 6 × 9 = 27."},{"id":"m-area-1-2","section":"math","domain":"geo","skill":"area","level":1,"type":"mc","question":"A triangle has a base of 12 centimetres and a height of 11 centimetres. What is its area, in square centimetres?","options":["23","46","66","132"],"answer":2,"explain":"Area = ½ × base × height = ½ × 12 × 11 = 66."},{"id":"m-area-2-1","section":"math","domain":"geo","skill":"area","level":2,"type":"mc","question":"A rectangle has a perimeter of 28 metres and a length of 11 metres. What is its area, in square metres?","options":["3","33","187","308"],"answer":1,"explain":"Perimeter = 2(length + width), so 11 + width = 14 and width = 3. Area = 11 × 3 = 33."},{"id":"m-area-2-2","section":"math","domain":"geo","skill":"area","level":2,"type":"mc","question":"A rectangle has a perimeter of 42 metres and a length of 15 metres. What is its area, in square metres?","options":["6","90","405","630"],"answer":1,"explain":"Perimeter = 2(length + width), so 15 + width = 21 and width = 6. Area = 15 × 6 = 90."},{"id":"m-area-3-1","section":"math","domain":"geo","skill":"area","level":3,"type":"mc","question":"Rectangle A has an area of 6 square centimetres. Every side of rectangle B is 3 times as long as the matching side of rectangle A. What is the area of rectangle B, in square centimetres?","options":["15","18","36","54"],"answer":3,"explain":"When lengths are multiplied by 3, areas are multiplied by 3² = 9: 6 × 9 = 54."},{"id":"m-ang-1-1","section":"math","domain":"geo","skill":"ang","level":1,"type":"mc","question":"Two angles of a triangle measure 78° and 73°. What is the measure of the third angle?","options":["17°","29°","151°","209°"],"answer":1,"explain":"The angles of a triangle add up to 180°: 180 − 78 − 73 = 29."},{"id":"m-ang-1-2","section":"math","domain":"geo","skill":"ang","level":1,"type":"mc","question":"Two angles of a triangle measure 29° and 45°. What is the measure of the third angle?","options":["61°","74°","106°","286°"],"answer":2,"explain":"The angles of a triangle add up to 180°: 180 − 29 − 45 = 106."},{"id":"m-ang-2-1","section":"math","domain":"geo","skill":"ang","level":2,"type":"mc","question":"Two parallel lines are crossed by a third line. Two of the angles formed lie between the parallel lines, on the same side of the third line. One of them measures 126°. What is the measure of the other?","options":["36°","54°","126°","234°"],"answer":1,"explain":"Interior angles on the same side of a line crossing two parallel lines add up to 180°: 180 − 126 = 54."},{"id":"m-ang-2-2","section":"math","domain":"geo","skill":"ang","level":2,"type":"mc","question":"In an isosceles triangle, the angle between the two equal sides measures 20°. What is the measure of each of the other two angles?","options":["20°","70°","80°","160°"],"answer":2,"explain":"The other two angles are equal and together make 180 − 20 = 160°, so each is 80°."},{"id":"m-ang-3-1","section":"math","domain":"geo","skill":"ang","level":3,"type":"spr","question":"Triangle ABC is similar to triangle DEF, with A matching D, B matching E and C matching F. AB = 4, BC = 6 and DE = 12. What is the length of EF?","accept":["18"],"values":[18],"explain":"The scale factor is DE / AB = 12 / 4 = 3. So EF = 3 × BC = 3 × 6 = 18."},{"id":"m-trig-1-1","section":"math","domain":"geo","skill":"trig","level":1,"type":"mc","question":"A right triangle has a hypotenuse of length 5 and one leg of length 3. What is the length of the other leg?","options":["2","3","4","8"],"answer":2,"explain":"b² = 5² − 3² = 25 − 9 = 16, so b = 4."},{"id":"m-trig-1-2","section":"math","domain":"geo","skill":"trig","level":1,"type":"mc","question":"A right triangle has a hypotenuse of length 17 and one leg of length 8. What is the length of the other leg?","options":["8","9","15","25"],"answer":2,"explain":"b² = 17² − 8² = 289 − 64 = 225, so b = 15."},{"id":"m-trig-2-1","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In right triangle PQR, the right angle is at Q. PQ = 4, QR = 3 and PR = 5. What is the value of cos P?","options":["3/5","3/4","4/5","4/3"],"answer":2,"explain":"For angle P the opposite side is QR = 3, the adjacent side is PQ = 4 and the hypotenuse is PR = 5. cos P = 4/5."},{"id":"m-trig-2-2","section":"math","domain":"geo","skill":"trig","level":2,"type":"mc","question":"In right triangle PQR, the right angle is at Q. PQ = 12, QR = 5 and PR = 13. What is the value of tan P?","options":["5/12","12/5","12/13","5/13"],"answer":0,"explain":"For angle P the opposite side is QR = 5, the adjacent side is PQ = 12 and the hypotenuse is PR = 13. tan P = 5/12."},{"id":"m-trig-3-1","section":"math","domain":"geo","skill":"trig","level":3,"type":"mc","question":"In right triangle ABC, the right angle is at C. If sin A = 7/25, what is the value of cos B?","options":["7/24","7/25","25/7","24/25"],"answer":1,"explain":"A and B are the two acute angles, so they add up to 90°. The cosine of B equals the sine of A: 7/25."},{"id":"m-circ-1-1","section":"math","domain":"geo","skill":"circ","level":1,"type":"mc","question":"A circle has a diameter of 10 centimetres. What is its circumference, in centimetres?","options":["20π","5π","10π","25π"],"answer":2,"explain":"Circumference = π × diameter = 10π."},{"id":"m-circ-1-2","section":"math","domain":"geo","skill":"circ","level":1,"type":"mc","question":"A circle has a radius of 9 centimetres. What is its area, in square centimetres?","options":["9π","18π","324π","81π"],"answer":3,"explain":"Area = πr² = π × 9² = 81π."},{"id":"m-circ-2-1","section":"math","domain":"geo","skill":"circ","level":2,"type":"mc","question":"In the xy-plane, a circle has the equation (x + 5)² + (y + 1)² = 16. What is the centre of the circle?","options":["(5, −1)","(−1, −5)","(5, 1)","(−5, −1)"],"answer":3,"explain":"In (x − h)² + (y − k)² = r² the centre is (h, k). Here that is (−5, −1), and the radius is 4."},{"id":"m-circ-2-2","section":"math","domain":"geo","skill":"circ","level":2,"type":"mc","question":"In the xy-plane, a circle has the equation (x − 6)² + (y − 5)² = 81. What is the centre of the circle?","options":["(5, 6)","(−6, 5)","(6, 5)","(−6, −5)"],"answer":2,"explain":"In (x − h)² + (y − k)² = r² the centre is (h, k). Here that is (6, 5), and the radius is 9."},{"id":"m-circ-3-1","section":"math","domain":"geo","skill":"circ","level":3,"type":"spr","question":"x² + y² − 4x − 4y − 41 = 0\n\nThe equation above represents a circle in the xy-plane. What is the radius of the circle?","accept":["7"],"values":[7],"explain":"Complete the square for x and for y: (x − 2)² + (y − 2)² = 41 + 4 + 4 = 49. The radius is √49 = 7."}];

